@@ -1,15 +1,19 @@
-// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
-// car elle empêche la coalescence parfaite des accès mémoire.
 struct Particle {
     float x, y, z;
     float vx, vy, vz;
     float mass;
 };

-// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
+enum { kSourceTileSize = 256 };
+
 extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
-    int i = blockIdx.x * blockDim.x + threadIdx.x;
-    if (i >= n) return;
+    const int i = blockIdx.x * blockDim.x + threadIdx.x;
+    const bool active = i < n;
+
+    __shared__ float tile_x[kSourceTileSize];
+    __shared__ float tile_y[kSourceTileSize];
+    __shared__ float tile_z[kSourceTileSize];
+    __shared__ float tile_mass[kSourceTileSize];

     const float G = 1.0f;
     const float softening = 0.001f;
@@ -18,35 +22,56 @@ extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, i
     float fy = 0.0f;
     float fz = 0.0f;

-    // Approche naïve : chaque thread parcourt toutes les particules en mémoire globale
-    // sans utiliser de mémoire partagée (__shared__) ni mettre in[i] en registre.
-    for (int j = 0; j < n; j++) {
-        if (i == j) continue; // Divergence de branche inutile dans la boucle
+    for (int tile_start = 0; tile_start < n;) {
+        int tile_count = n - tile_start;
+        if (tile_count > kSourceTileSize) {
+            tile_count = kSourceTileSize;
+        }
+
+        for (int k = threadIdx.x; k < tile_count; k += blockDim.x) {
+            const int source_index = tile_start + k;
+            tile_x[k] = in[source_index].x;
+            tile_y[k] = in[source_index].y;
+            tile_z[k] = in[source_index].z;
+            tile_mass[k] = in[source_index].mass;
+        }
+        __syncthreads();

-        float dx = in[j].x - in[i].x;
-        float dy = in[j].y - in[i].y;
-        float dz = in[j].z - in[i].z;
+        if (active) {
+            for (int k = 0; k < tile_count; ++k) {
+                const int j = tile_start + k;
+                if (i == j) {
+                    continue;
+                }

-        float distSq = dx * dx + dy * dy + dz * dz + softening;
-        float dist = sqrtf(distSq); // Calcul coûteux (au lieu de rsqrtf)
+                const float dx = tile_x[k] - in[i].x;
+                const float dy = tile_y[k] - in[i].y;
+                const float dz = tile_z[k] - in[i].z;

-        float f = (G * in[i].mass * in[j].mass) / (distSq * dist);
+                const float distSq = dx * dx + dy * dy + dz * dz + softening;
+                const float dist = sqrtf(distSq);
+                const float f = (G * in[i].mass * tile_mass[k]) / (distSq * dist);

-        fx += f * dx;
-        fy += f * dy;
-        fz += f * dz;
+                fx += f * dx;
+                fy += f * dy;
+                fz += f * dz;
+            }
+        }
+
+        __syncthreads();
+        tile_start += tile_count;
     }

-    // Intégration d'Euler explicite
-    Particle p = in[i];
-    p.vx += (fx / p.mass) * dt;
-    p.vy += (fy / p.mass) * dt;
-    p.vz += (fz / p.mass) * dt;
+    if (active) {
+        Particle p = in[i];
+        p.vx += (fx / p.mass) * dt;
+        p.vy += (fy / p.mass) * dt;
+        p.vz += (fz / p.mass) * dt;

-    p.x += p.vx * dt;
-    p.y += p.vy * dt;
-    p.z += p.vz * dt;
+        p.x += p.vx * dt;
+        p.y += p.vy * dt;
+        p.z += p.vz * dt;

-    out[i] = p;
+        out[i] = p;
+    }
 }
